js::Json json;
try {
  json = js::parse(fileText);
} catch (const std::invalid_argument&) {
  return;
}
// JS 真值。null 同时代表 undefined。
const auto truthy = [](const js::Json& v) {
  if (v.is_null()) {
    return false;
  }
  if (v.is_boolean()) {
    return v.get<bool>();
  }
  if (v.is_number()) {
    return v.get<double>() != 0;
  }
  if (v.is_string()) {
    return !v.get_ref<const std::string&>().empty();
  }
  return true;  // 对象、数组
};
// v?.key：只有 JSON 对象有这些键，其他值（null、数字、字符串、数组）读到 undefined，记为 null
const auto member = [](const js::Json& v, const char* key) {
  if (v.is_object()) {
    if (const auto it = v.find(key); it != v.end()) {
      return *it;
    }
  }
  return js::Json();
};
// notifications.monitor -> notifications.forceMonitor
const js::Json notifications = member(json, "notifications");
const js::Json oldMonitor = member(notifications, "monitor");
if (truthy(oldMonitor) && !truthy(member(notifications, "forceMonitor"))) {
  auto* forceMonitor = this->options->notifications.get()->forceMonitor.get();
  // ?? 只替换 null/undefined；赋给 bool 属性时 V4 按 JS 真值转换
  const js::Json enable = member(oldMonitor, "enable");
  forceMonitor->enable.set(enable.is_null() ? false : truthy(enable));
  // 赋给 string 属性：数字、布尔经 QVariant 转成字符串；对象、数组转换失败，V4 抛出异常
  const js::Json name = member(oldMonitor, "name");
  if (name.is_null()) {
    forceMonitor->name.set("");
  } else if (name.is_string()) {
    forceMonitor->name.set(name.get<std::string>());
  } else if (name.is_boolean()) {
    forceMonitor->name.set(name.get<bool>() ? "true" : "false");
  } else if (name.is_number()) {
    forceMonitor->name.set(js::toString(name.get<double>()));
  } else {
    throw std::runtime_error(std::string("Cannot assign ") + (name.is_object() ? "QVariantMap" : "QVariantList") +
                             " to QString");
  }
}

