std::vector<std::string> keys = js::split(nestedKey, ".");
qs::JsonObject* obj = this->options;  // an alias of the adapter
// Traverse the parent objects. In QML a missing or non-object step is replaced by a new JS
// object ({}), which isn't part of the adapter and so changes nothing that is saved; here the
// call stops instead (a deviation that changes nothing observable).
for (std::size_t i = 0; i + 1 < keys.size(); ++i) {
  qs::JsonObject* next = obj != nullptr ? obj->child(keys[i]) : nullptr;
  if (next == nullptr) {
    js::warn("setNestedValue:", nestedKey, "does not name a nested option");
    return;
  }
  obj = next;
}
// Convert value to correct type using JSON.parse when safe
js::Json convertedValue = value;
if (value.is_string()) {
  const std::string trimmed = js::trim(value.get<std::string>());
  if (trimmed == "true" || trimmed == "false" || !std::isnan(js::toNumber(trimmed))) {
    try {
      convertedValue = js::parse(trimmed);
    } catch (const std::exception&) {
      convertedValue = value;
    }
  }
}
obj->setValue(keys.back(), convertedValue);

